    // Excel Report Templates Module
    // Contains functions to generate Excel reports using SheetJS (xlsx)


    // Global XLSX instance
    let XLSX = null;
    let xlsxLoadPromise = null; // Cache the loading promise

    // Initialize XLSX library with lazy loading
    async function initXLSX() {
        if (XLSX) {
            return XLSX; // Already loaded
        }

        if (xlsxLoadPromise) {
            return xlsxLoadPromise; // Already loading, return cached promise
        }

        // Load XLSX library lazily (only when needed)
        xlsxLoadPromise = new Promise((resolve, reject) => {
            // Check if XLSX is already in window (loaded by other means)
            if (window.XLSX) {
                XLSX = window.XLSX;
                resolve(XLSX);
                return;
            }

            // Dynamically load XLSX library
            const script = document.createElement('script');
            script.src = 'https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js';
            script.async = true;
            script.onload = () => {
                XLSX = window.XLSX;
                resolve(XLSX);
            };
            script.onerror = () => {
                reject(new Error('Failed to load XLSX library'));
            };
            document.head.appendChild(script);
        });

        return xlsxLoadPromise;
    }

    // ============================
    // UTILITY FUNCTIONS
    // ============================

    /**
     * Create workbook with standard formatting
     * @returns {Object} XLSX workbook
     */
    async function createWorkbook() {
        await initXLSX();
        const wb = XLSX.utils.book_new();

        // Add metadata
        wb.Props = {
            Title: 'Laporan Keuangan RT',
            Subject: 'Generated Report',
            Author: 'Sistem Informasi Blok H',
            CreatedDate: new Date()
        };

        return wb;
    }

    /**
     * Add header row to worksheet
     * @param {Array} ws_data - Worksheet data array
     * @param {Array} headers - Header array
     * @param {number} startRow - Starting row index
     * @returns {number} Next row index
     */
    function addHeaderRow(ws_data, headers, startRow = 0) {
        // Title row
        ws_data[startRow] = [
            { v: 'SISTEM INFORMASI KEUANGAN', t: 's', s: { font: { bold: true, sz: 16 }, alignment: { horizontal: 'center' } } }
        ];
        ws_data[startRow + 1] = [
            { v: 'BLOK H CIKEAS GARDENIA', t: 's', s: { font: { bold: true, sz: 14 }, alignment: { horizontal: 'center' } } }
        ];

        // Empty row
        ws_data[startRow + 2] = [];

        return startRow + 3;
    }

    /**
     * Format currency cell
     * @param {number} value - Numeric value
     * @returns {Object} Formatted cell object
     */
    function formatCurrencyCell(value) {
        return {
            v: value,
            t: 'n',
            s: {
                numFmt: '"Rp" #,##0',
                alignment: { horizontal: 'right' }
            }
        };
    }

    /**
     * Format header cell
     * @param {string} text - Header text
     * @returns {Object} Formatted cell object
     */
    function formatHeaderCell(text) {
        return {
            v: text,
            t: 's',
            s: {
                font: { bold: true },
                fill: { fgColor: { rgb: 'FFD3D3D3' } },
                alignment: { horizontal: 'center' }
            }
        };
    }

